from collections import deque, defaultdict

def solution(input_str):
    lines = input_str.strip().split('\n')
    n, m = map(int, lines[0].split())
    s, t = map(int, lines[1].split())

    # Build adjacency list: adj[u] = list of (v, edge_index)
    adj = defaultdict(list)

    # Store edges as (u, v, w, edge_index)
    edges = []

    for i in range(m):
        u, v, w = map(int, lines[2 + i].split())
        adj[u].append((v, i + 1))
        adj[v].append((u, i + 1))
        edges.append((u, v, w, i + 1))

    # Check if s and t are already disconnected
    def bfs(s, t, excluded_edges):
        visited = set()
        queue = deque([s])
        visited.add(s)

        while queue:
            u = queue.popleft()
            if u == t:
                return True
            for v, eid in adj[u]:
                if v not in visited and eid not in excluded_edges:
                    visited.add(v)
                    queue.append(v)
        return False

    # Check 0 edges
    if not bfs(s, t, set()):
        return "0\n0\n"

    min_cost = float('inf')
    best_option = None

    # Try 1 edge removal
    for _, _, cost, eid in edges:
        if not bfs(s, t, {eid}):
            if cost < min_cost:
                min_cost = cost
                best_option = (1, eid)

    if best_option:
        sol_type, eid = best_option
        return f"{min_cost}\n{sol_type}\n{eid}\n"

    # Try 2 edges removal
    for i in range(m):
        u1, v1, w1, eid1 = edges[i]
        for j in range(i + 1, m):
            u2, v2, w2, eid2 = edges[j]

            excluded = {eid1, eid2}
            if not bfs(s, t, excluded):
                total_cost = w1 + w2
                if total_cost < min_cost:
                    min_cost = total_cost
                    best_option = (2, eid1, eid2)

    if best_option:
        sol_type, eid1, eid2 = best_option
        return f"{min_cost}\n{sol_type}\n{eid1} {eid2}\n"

    return "-1\n"

