from functools import lru_cache

class Grinde:
    def __init__(self, k):
        self.k = k
        self.memo = {0: 0, 1: 1}

    @lru_cache(maxsize=None)
    def compute(self, n):
        """Compute Grundy number for a pile of size n"""
        if n in self.memo:
            return self.memo[n]

        if n == 0:
            return 0

        mex = set()

        # Option 1: Remove 1 cow
        mex.add(self.compute(n - 1))

        # Option 2: Split if even (only if k is odd to have non-zero XOR)
        if n % 2 == 0 and k % 2 == 1:
            half = n // 2
            mex.add(self.compute(half))

        # Find mex
        result = 0
        while result in mex:
            result += 1

        self.memo[n] = result
        return result


def solution(input_data):
    lines = input_data.strip().split('\n')
    n, k = map(int, lines[0].split())
    a = list(map(int, lines[1].split()))

    grinde = Grinde(k)

    xor_sum = 0
    for pile in a:
        xor_sum ^= grinde.compute(pile)

    if xor_sum != 0:
        return "Kevin"
    else:
        return "Nicky"


