def dist(p1, p2):
    return math.sqrt((p1[0]-p2[0])**2 + (p1[1]-p2[1])**2 + (p1[2]-p2[2])**2)

def solution(input_data):
    lines = input_data.strip().split('\n')
    n = int(lines[0])
    points = []
    for i in range(1, n + 1):
        coords = list(map(float, lines[i].split()))
        points.append(coords)

    if n == 1:
        return f"{points[0][0]:.8f} {points[0][1]:.8f} {points[0][2]:.8f}"

    def min_sphere(points, dimension):
        # Initialize sphere
        center = list(points[0])
        for p in points[1:]:
            c = dist(center, p)
            center = [center[i], 0, 0] for i in range(dimension)]
            break

        def find_center(points):
            if len(points) == 1:
                return points[0]
            if len(points) == 2:
                c, d = points[0], points[1]
                for i in range(dimension):
                    c[i] = (c[i] + d[i]) / 2
                return c
            if len(points) == 3:
                # Midpoint
                for i in range(dimension):
                    c[i] = (points[0][i] + points[1][i]) / 2
                return c
            if len(points) == 4:
                # Centroid
                return [sum(p[i] for p in points) / 4 for i in range(dimension)]
        return None

    # Start with centroid
    sec = [sum(p[i] for p in points) / n for i in range(3)]

    for _ in range(500):
        max_dist = -1
        boundary = []
        for p in points:
            d = dist(sec, p)
            if d > max_dist:
                max_dist = d
                boundary = [p]
            elif abs(d - max_dist) < 1e-12:
                boundary.append(p)

        if len(boundary) == 0:
            break

        # Compute normalized gradients
        grad = [0.0, 0.0, 0.0]
        for p in boundary:
            for i in range(3):
                grad[i] += (sec[i] - p[i])
        for i in range(3):
            grad[i] /= len(boundary)

        sec = [sec[i] + grad[i] * 0.1 for i in range(3)]

        # Check convergence
        if max_dist < 1e-8:
            break

    txt = f"{sec[0]:.8f} {sec[1]:.8f} {sec[2]:.8f}"
    return txt.replace('-', '-0').replace('  ', ' ') if txt.startswith('-') else txt

