import math

def solution(input_str):
    lines = input_str.strip().split('\n')
    n, m = map(int, lines[0].split())

    ops = []
    for i in range(1, n + 1):
        parts = lines[i].split()
        t = int(parts[0])
        x_prime = int(parts[1])
        y = int(parts[2])
        x = x_prime / 100000.0
        ops.append((t, x, y))

    # first_seen[j] = earliest time-step to reach exactly j bananas, or inf if unreachable
    first_seen = [float('inf')] * (m + 1)
    first_seen[0] = 0

    # Set of values reachable at current step
    reachable = {0}

    for step, (t, x, y) in enumerate(ops, 1):
        # New values that become reachable at this or previous steps
        new_reachable = set(reachable)

        for k in reachable:
            # Apply the operation from 0 to y times
            for a in range(y + 1):
                current = k
                for _ in range(a):
                    if t == 1:
                        # Type 1: k := ceil(k + x)
                        current = math.ceil(current + x)
                    else:
                        # Type 2: k := ceil(k * x)
                        current = math.ceil(current * x)

                    # Track first time we see this value
                    if 0 < current <= m and step < first_seen[current]:
                        first_seen[current] = step
                new_reachable.add(current)

        # Update reachable set for next iteration
        reachable = new_reachable

    # Build final answer (for bananas 1 to m)
    result = []
    for j in range(1, m + 1):
        if first_seen[j] <= n:
            result.append(str(first_seen[j]))
        else:
            result.append("-1")

    return ' '.join(result)

