        elif c == 'Y':
            # Must treat as 'Y'
            for (max_s, curr) in dp:
                new_dp.add((max_s, 0))
        else:  # c == '?'
            # Can treat as either 'N' or 'Y'
            for (max_s, curr) in dp:
                new_dp.add((max(max_s, curr + 1), curr + 1))  # Choose 'N'
                new_dp.add((max_s, 0))  # Choose 'Y'
        dp = new_dp

    # Check if any state achieves exactly k maximum consecutive N's
    for (max_s, curr) in dp:
        if max_s == k:
            return "YES"
    return "NO"

