from itertools import permutations

def solution(input_str):
    lines = input_str.strip().split('\n')
    n = int(lines[0])

    # Build cost matrix: cost[i][j] = cost for city i to connect to city j
    cost = [[0] * (n + 1) for _ in range(n + 1)]

    for i in range(1, n + 1):
        row = list(map(int, lines[i].split()))
        row_idx = 0
        for j in range(1, n + 1):
            if j != i:
                cost[i][j] = row[row_idx]
                row_idx += 1

    def is_stable(matching):
        """Check if a perfect matching is stable (no blocking pairs)"""
        for i in range(1, n + 1):
            partner = matching[i]
            for k in range(1, n + 1):
                if i != k:
                    # Check if both i and k would prefer each other
                    if cost[i][k] < cost[i][partner] and cost[k][i] < cost[k][matching[k]]:
                        return False
        return True

    # For small N, try all permutations
    if n <= 7:
        for perm in permutations(range(1, n + 1)):
            matching = {i: perm[i-1] for i in range(1, n + 1)}

            if is_stable(matching):
                return '\n'.join(str(matching[i]) for i in range(1, n + 1))
        return '-1'

    # For larger N, use greedy matching with stability check
    # This is more complex, so we try to find any stable matching
    matching = {}

    def try_stable_matching(pairs, available):
        if len(available) == 0:
            for i, partner in pairs.items():
                if i not in matching:
                    matching[i] = partner
            return matching

        city = available[0]
        for partner in available:
            if city != partner:
                test_matching = matching.copy()
                test_matching[city] = partner
                if partner not in test_matching:
                    test_matching[partner] = city

                # Check if this partial matching is stable so far
                is_valid = True
                for i, p in test_matching.items():
                    if i != city and i != partner:
                        curr_other = matching.get(i)
                        if curr_other is None:
                            continue
                        if cost[i][p] < cost[i][curr_other] and cost[p][i] < cost[p][matching.get(p, p)]:
                            is_valid = False
                            break

                if is_valid:
                    test = {i: partner if i == city else test_matching.get(i) for i, val in matching.items() if i != partner}
                    test[city] = partner
                    test[partner] = city
                    result = try_stable_matching(test, available[1:])
                    if result:
                        return result

        return None

    result = try_stable_matching({}, set(range(1, n + 1)))

    if result:
        final = {i: result[i] for i in range(1, n + 1)}
        return '\n'.join(str(final[i]) for i in range(1, n + 1))

    return '-1'

