    # Returns list of employees (1-indexed) or None if impossible

    def dfs(mask, counts):
        # mask: bitmask of who is invited
        # counts: list of message counts for each employee

        # Check current state
        if all(counts[i] != predictions[i] for i in range(n)):
            return mask

