    from itertools import combinations

    best_mask = None

    for r in range(n + 1):
        if best_mask is not None:
            break

        for party in combinations(range(n), r):
            # Build actual message counts for this party
            counts = [0] * n

            for person in party:
                # Person sends messages to people in their contact list
