from collections import deque
from typing import Set, Tuple

def solution(input_str: str) -> str:
    lines = input_str.strip().split('\n')
    k_str = lines[0]
    k_parts = k_str.split()
    k = int(k_parts[0])
    n = int(k_parts[1]) if len(k_parts) > 1 else 0

    blocked: Set[Tuple[int, int]] = set()
    for i in range(1, min(n + 1, len(lines))):
        line = lines[i].strip()
        if not line:
            continue
        coords = list(map(int, line.split()))
        if len(coords) >= 2:
            blocked.add(tuple(coords[:2]))

    # Base case: 0 moves
    if k == 0:
        return "1\n" if (0, 0) not in blocked else "0\n"

    MOVES = [(-2, -1), (-2, 1), (-1, -2), (-1, 2), 
             (1, -2), (1, 2), (2, -1), (2, 1)]

    def min_knight_moves(x: int, y: int) -> int:
        """Calculate minimum knight moves to reach (x,y) from (0,0)"""
        if x < 0:
            x = -x
        if y < 0:
            y = -y

        if x == 0 and y == 0:
            return 0
        if x == 1 and y == 0 or x == 1 and y == 2:
            return 3

        if x == 2 and y == 2:
            return 4
        if x == 2 and y == 0:
            return 2

        max_coord = max(x, y)
        if max_coord <= 10:
            from functools import lru_cache
            @lru_cache(maxsize=None)
            def bfs(mx: int, my: int) -> int:
                if mx == 0 and my == 0:
                    return 0
                if mx < 0 or my < 0:
                    return float('inf')

                q = deque([(mx, my)])
                dist = {(mx, my): 0}
                while q:
                    curr_x, curr_y = q.popleft()
                    d = dist[(curr_x, curr_y)]
                    if d > k:  # BFS limit
                        continue
                    for dx, dy in MOVES:
                        nx, ny = curr_x - dx, curr_y - dy
                        if (nx, ny) not in dist and 0 <= nx <= 10000 and 0 <= ny <= 10000:
                            if nx == 0 and ny == 0:
                                return d + 1
                            dist[(nx, ny)] = d + 1
                            q.append((nx, ny))
                return float('inf')
            return bfs(x, y)
        return 0

    # For very large k, the number of reachable squares follows a pattern
    # The pattern is: (9*k^2 + 118*k + 124)/4 - blocked_squares_contributions
    # But we need to be careful about the exact formula

    # Actually, let's use a smarter approach:
    # For k >= 1000, most squares are reachable.
    # The number follows a quadratic pattern minus blocked influence

    # The formula for reachable squares (without blocks) grows as:
    # n_kw = (9*k^2 + 118*k + 124) // 4

    if k <= 1000:
        # Use BFS for smaller k values
        visited: Set[Tuple[int, int]] = set()
        queue = deque([(0, 0, 0)])  # (x, y, moves)
        count = 0

        while queue:
            x, y, moves = queue.popleft()
            if x in visited and y in visited:
                continue
            visited.add((x, y))
            count += 1

            if moves == k:
                continue

            for dx, dy in MOVES:
                nx, ny = x + dx, y + dy
                # Prune if too far - only explored if we haven't exceeded reasonable bounds
                if abs(nx) <= abs(max(int(k**0.35), 20)) and abs(ny) <= abs(max(int(k**0.35), 20)):
                    if (nx, ny) not in visited and (nx, ny) not in blocked:
                        queue.append((nx, ny, moves + 1))

        return str(count % 1000000007) + "\n"
    else:
        MOD = 1000000007
        # For large k, use the known formula for knight reachability
        # The number of squares reachable in at most k moves on 8x8 board
        # grows as a quadratic function

        n_kw = (9 * k * k + 118 * k + 124) // 4
        n_kw = n_kw % MOD

        # The blocked squares' effect diminishes, but we should account for them
        # Since k is large, most blocked areas are within the kernel

        # Count blocked squares in a reasonable region
        blocked_count = 0
        for bx, by in blocked:
            if min_knight_moves(bx - 0, by - 0) <= k:
                # If reachable within distance k, it's a hole
                # For counting purposes, we subtract contributions
                blocked_count += 1

        # Adjust for overcounting and pattern
        result = (n_kw - blocked_count + MOD) % MOD
        return str(result) + "\n"


