def solution(input_data: str) -> str:
    lines = input_data.strip().split('\n')
    if not lines:
        return '0\n'

    try:
        n, m = map(int, lines[0].split())
    except:
        return '0\n'

    # Handle case where there are no edges
    if m == 0:
        # No edges means we can't have any edge with weight 0, 1, or 2
        return '0\n'

    # Build adjacency list (convert to 0-indexed)
    adj = [[] for _ in range(n + 1)]
    edge_set = set()
    for i in range(1, m + 1):
        u, v = map(int, lines[i].split())
        adj[u].append(v)
        adj[v].append(u)
        edge_set.add((min(u, v), max(u, v)))

    # Find connected components
    visited = [False] * (n + 1)
    components = []

    def get_component(start):
        comp = []
        stack = [start]
        visited[start] = True
        while stack:
            node = stack.pop()
            comp.append(node)
            for neighbor in adj[node]:
                if not visited[neighbor]:
                    visited[neighbor] = True
                    stack.append(neighbor)
        return comp

    for i in range(1, n + 1):
        if not visited[i]:
            comp = get_component(i)
            components.append(comp)

    comp_count = len(components)

    # Count isolated vertex components (components with no edges)
    isolated_count = 0
    for comp in components:
        has_internal_edge = False
        for u in comp:
            for v in adj[u]:
                if v in edge_set:  # Edge connected to something in current component
                    has_internal_edge = True
                    break
            if has_internal_edge:
                break
        if not has_internal_edge:
            isolated_count += 1

    # P1: no edge has weight 1 (monochromatic components)
    p1 = 1 << comp_count

    # P0 ∩ P1: components with edges must be all 1, isolated can be 0 or 1
    p01 = 1 << isolated_count

    # P1 ∩ P2: components with edges must be all 0, isolated can be 0 or 1
    p12 = 1 << isolated_count

    # P0 ∩ P2: proper 2-colorings (must be bipartite)
    p02 = 0
    for comp in components:
        if is_bipartite_component(comp, adj):
            p02 += 2

    # P0 ∩ P1 ∩ P2: only possible when no edges (already handled above)
    p012 = 0 if m > 0 else (1 << n) if m == 0 else 0

    # Count independent sets for P0
    # This is the number of ways to assign 0s/1s such that no edge has both endpoints as 0
    # which means the 0-set forms an independent set
    # P2 is the same by symmetry (1-set forms independent set)
    p0 = count_independent_sets(adj)
    p2 = p0

    # Inclusion-exclusion: |P0 ∪ P1 ∪ P2| = |P0| + |P1| + |P2| - |P0∩P1| - |P0∩P2| - |P1∩P2| + |P0∩P1∩P2|
    union_size = p0 + p1 + p2 - p01 - p02 - p12 + p012

    total = 1 << n
    result = total - union_size

    return str(result) + '\n'

def is_bipartite_component(comp, adj):
    """Check if a component is bipartite"""
    visited = {}
    try:
        stack = [comp[0]]
        color = {comp[0]: 0}
        while stack:
            node = stack.pop()
            for neighbor in adj[node]:
                if neighbor not in visited:
                    color[neighbor] = 1 - color[node]
                    visited[neighbor] = True
                    stack.append(neighbor)
                elif color.get(neighbor) == color.get(node):
                    return False
        return True
    except:
        return False

def count_independent_sets(adj):
    """Count all independent sets using recursive algorithm"""
    n = len(adj) - 1

    # Convert to 0-indexed
    adj0 = [[v - 1 for v in adj[u]] for u in adj]
    adj0 = adj0[:n+1]

    memo = {}

    def count_ind(idx):
        if idx == n + 1:
            return 1

        mask = 0
        for i in range(idx):
            if adj0[i] and i not in [v-1 for v in adjacency[i]] if hasattr(count_ind, 'adjacency') else True:
                mask |= (1 << i)

        if mask in memo:
            return memo[mask]

        # Option 1: Don't include vertex idx in independent set
        res1 = count_ind(idx + 1)

        # Option 2: Include vertex idx (then can't include neighbors)
        res2 = 0
        neighbors = adj0[idx]
        if neighbors:
            # Check if idx can be included
            for v in neighbors:
                if v < idx:
                    res2 += count_ind(idx + 1)
                    break  # Skip this option if we picked idx

        memo[mask] = res1 + res2 if not neighbors else res1
        return res1

    return count_ind(1)

