            # Collect options from top and left neighbors
            options = []
            if i > 0:
                for f2, f5 in dp[i-1][j]:
                    options.append((f2 + count_factors(matrix[i][j], 2), f5 + count_factors(matrix[i][j], 5)))
            if j > 0:
                for f2, f5 in dp[i][j-1]:
                    options.append((f2 + count_factors(matrix[i][j], 2), f5 + count_factors(matrix[i][j], 5)))

            if not options:
                continue

            # Find Pareto-optimal pairs (no pair dominates another)
            pareto = []
            for p in options:
                is_dominated = False
                for q in options:
                    # q dominates p if q has <= factors in both 2 and 5
                    # and strictly less in at least one
                    if q[0] <= p[0] and q[1] <= p[1] and (q[0] < p[0] or q[1] < p[1]):
                        is_dominated = True
                        break
                if not is_dominated:
                    pareto.append(p)

            dp[i][j] = pareto

    # Find minimum trailing zeros at destination
    ans_pairs = dp[n-1][n-1]
    min_trailing_zeros = min(min(p[0], p[1]) for p in ans_pairs)

