            for p in dp[i][j]:
                prev_p2, prev_p5 = p[0] - f2_cell, p[1] - f5_cell
                if any(prev_p2 == q[0] and prev_p5 == q[1] for q in dp[i-1][j]):
                    path_chars.append('D')
                    i -= 1
                    found = True
                    break

        if not found and j > 0:
            for p in dp[i][j]:
                prev_p2, prev_p5 = p[0] - f2_cell, p[1] - f5_cell
                if any(prev_p2 == q[0] and prev_p5 == q[1] for q in dp[i][j-1]):
                    path_chars.append('R')
                    j -= 1
                    found = True
                    break

        # Default: use any valid predecessor
        if not found:
            if i > 0:
                path_chars.append('D')
                i -= 1
            else:
                path_chars.append('R')
                j -= 1

    return f"{min_trailing_zeros}\n{''.join(path_chars[::-1])}"

