def solution(input_str):
    lines = input_str.strip().split('\n')
    n, k = map(int, lines[0].split())
    s = lines[1]

    # Track all possible states: at each position, which differences are reachable
    # parent[(i, d)] = (prev_d, char) to reconstruct solution
    parent = {(0, 0): (None, None)}
    current_states = {0}

    for i in range(n):
        new_states = {}
        allowed = []
        if s[i] == 'W':
