        for d in current_states:
            for choice in allowed:
                if choice == 'W':
                    new_d = d + 1
                elif choice == 'L':
                    new_d = d - 1
                else:
                    new_d = d

                # Check if this path is valid
                if abs(d) == k:
                    # Already at k, can't continue
                    continue

                if i + 1 == n and abs(new_d) == k:
                    # Final position must have |d| = k
                    new_states[(i + 1, new_d)] = (d, choice)
