                    # Not final, check new state doesn't hit k
                    if abs(new_d) != k:
                        new_states[(i + 1, new_d)] = (d, choice)

        parent.update(new_states)
        current_states = {new_d for (i, new_d) in new_states if new_d > 0}
        if not current_states:
            current_states |= {new_d for (i, new_d) in parent if i + 1 == n and abs(new_d) == k}

    # Check if we have any valid final state
    valid_final = [d for (i, d) in parent if i == n and abs(d) == k]

