import sys

def get_divisors(n):
    divs = []
    i = 1
    while i * i <= n:
        if n % i == 0:
            divs.append(i)
            if i * i != n:
                divs.append(n // i)
        i += 1
    return sorted(divs)

def check_valid(n, m, matrix, r, c):
    if n % r != 0 or m % c != 0:
        return False

    # Get the reference block (first block)
    expected = matrix[0:r][0:c]

    # Check all blocks
    for block_i in range(n // r):
        for block_j in range(m // c):
            row_start = block_i * r
            col_start = block_j * c
            current = matrix[row_start:row_start + r][col_start:col_start + c]
            if current != expected:
                return False
    return True

def parse_matrix(lines, n, m):
    matrix = []
    for line in lines:
        line = line.strip()
        if not line:
            continue
        parts = line.split()
        if len(parts) == m:
            matrix.append(list(map(int, parts[:m])))
    if len(matrix) < n:
        # Pad if needed
        for _ in range(n - len(matrix)):
            matrix.append([0] * m)
    return matrix

