    def can_win(a, b):
        if (a, b) in memo:
            return memo[(a, b)]

        # Check if already at or beyond losing threshold
        if pow(a, b) >= n:
            memo[(a, b)] = False
            return False

        # Try both moves - winning if we can force opponent to lose
        win = False

        # Move 1: Add box
        apowb = pow(a + 1, b)
        if apowb < n:
            if not can_win(a + 1, b):
