        # Move 2: Add item
        if not win:
            apowb = pow(a, b + 1)
            if apowb < n:
                if not can_win(a, b + 1):
                    win = True

        memo[(a, b)] = win
        return win

    # If Stas can win from initial position, Masha loses
    if can_win(a, b):
        return "Stas\n\n"
    else:
        # Stas cannot win, Masha wins
        return "Masha\n\n"

