    # dp[i] = maximum important count achievable with cumulative height i
    max_height = sum(a)
    dp = [0] * (max_height + 1)
    dp[0] = 0

    # We process all boxes one by one
    # At each step, decide where to place this box

    for h in important:
        for i in range(max_height, h - 1, -1):
            if dp[i - h] > 0 or i >= l and i - h < r:
                dp[i] = max(dp[i], dp[i - h])

    return dp[0]

from collections import deque

def solution(n_str):
    n = int(n_str)

    if n == 0:
        return "0\n"

    memo = {}
    queue = deque([(n, 0)])
    visited = {n}

    while queue:
        current, steps = queue.popleft()

        if current == 0:
            return str(steps) + "\n"

        if current in memo:
            continue

        digits = set(str(current))
        digits_int = set(int(d) for d in digits)

        # Try all possible subtractions
        for digit in digits_int:
            new_num = current - digit
            if new_num not in visited and new_num >= 0:
                visited.add(new_num)
                queue.append((new_num, steps + 1))

    # Fallback if no solution found
    return "0\n"
